import { BASELINE_VOICE_NAV_SYSTEM_PROMPT } from "./prompts.js";

export function ResolveSystemPrompt(configured: string | undefined): string
{
  const trimmed = configured?.trim();
  if (trimmed !== undefined && trimmed.length > 0)
  {
    return trimmed;
  }

  return BASELINE_VOICE_NAV_SYSTEM_PROMPT;
}

export function ResolveOpenAiApiKey(
  secretValue: string | undefined,
  settingValue: string | undefined,
  envValue: string | undefined,
): string | undefined
{
  const fromSecret = secretValue?.trim();
  if (fromSecret !== undefined && fromSecret.length > 0)
  {
    return fromSecret;
  }

  const fromSetting = settingValue?.trim();
  if (fromSetting !== undefined && fromSetting.length > 0)
  {
    return fromSetting;
  }

  const fromEnv = envValue?.trim();
  if (fromEnv !== undefined && fromEnv.length > 0)
  {
    return fromEnv;
  }

  return undefined;
}

import * as vscode from "vscode";

import { ResolveOpenAiApiKey, ResolveSystemPrompt } from "./configCore.js";

export { ResolveOpenAiApiKey, ResolveSystemPrompt } from "./configCore.js";

const x_configSection = "sheaf.realtime";
const x_secretKeyOpenAiApiKey = "sheaf.realtime.openAiApiKey";

export async function getOpenAiApiKey(context: vscode.ExtensionContext): Promise<string | undefined>
{
  const secret = await context.secrets.get(x_secretKeyOpenAiApiKey);
  const setting = vscode.workspace.getConfiguration(x_configSection).get<string>("openAiApiKey");
  return ResolveOpenAiApiKey(secret ?? undefined, setting, process.env.OPENAI_API_KEY);
}

export function getModel(): string
{
  const value = vscode.workspace.getConfiguration(x_configSection).get<string>("model");
  return value !== undefined && value.trim().length > 0 ? value.trim() : "gpt-realtime-2";
}

export function getSystemPrompt(): string
{
  const value = vscode.workspace.getConfiguration(x_configSection).get<string>("systemPrompt");
  return ResolveSystemPrompt(value);
}

export function getInputDevice(): string | undefined
{
  const value = vscode.workspace.getConfiguration(x_configSection).get<string>("inputDevice");
  const trimmed = value?.trim();
  return trimmed !== undefined && trimmed.length > 0 ? trimmed : undefined;
}

export function getSafetyIdentifier(): string | undefined
{
  const value = vscode.workspace.getConfiguration(x_configSection).get<string>("safetyIdentifier");
  const trimmed = value?.trim();
  return trimmed !== undefined && trimmed.length > 0 ? trimmed : undefined;
}

import * as vscode from "vscode";

export interface LogSink
{
  Line(message: string): void;
  Error(message: string, err?: unknown): void;
}

export class Log implements LogSink
{
  constructor(private readonly m_channel: vscode.OutputChannel) {}

  Line(message: string): void
  {
    this.m_channel.appendLine(message);
  }

  Error(message: string, err?: unknown): void
  {
    const detail = err instanceof Error ? err.stack ?? err.message : String(err);
    this.m_channel.appendLine(`${message}${detail ? `: ${detail}` : ""}`);
  }

  Show(): void
  {
    this.m_channel.show(true);
  }
}

import assert from "node:assert/strict";
import { test } from "node:test";

import { ResolveOpenAiApiKey } from "../../src/vscode-extension/src/configCore.js";

test("ResolveOpenAiApiKey prefers SecretStorage over setting over env", () =>
{
  assert.equal(
    ResolveOpenAiApiKey("secret", "setting", "env"),
    "secret",
  );
  assert.equal(ResolveOpenAiApiKey(undefined, "setting", "env"), "setting");
  assert.equal(ResolveOpenAiApiKey(undefined, "", "env"), "env");
  assert.equal(ResolveOpenAiApiKey(undefined, undefined, "  "), undefined);
});

test("ResolveOpenAiApiKey ignores blank higher-priority values", () =>
{
  assert.equal(ResolveOpenAiApiKey("   ", "setting", undefined), "setting");
  assert.equal(ResolveOpenAiApiKey(undefined, "  \t", "env"), "env");
});

{
  "name": "sheaf-vscode-extension",
  "displayName": "Sheaf",
  "description": "Voice-driven realtime agent for VS Code (Sheaf)",
  "version": "0.0.1",
  "publisher": "sheaf",
  "private": true,
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Other"
  ],
  "activationEvents": [
    "onCommand:sheaf.realtime.toggleSession",
    "onCommand:sheaf.realtime.commitAndRespond",
    "onView:sheaf.chatView"
  ],
  "main": "./out/extension.js",
  "contributes": {
    "viewsContainers": {
      "activitybar": [
        {
          "id": "sheafContainer",
          "title": "Sheaf",
          "icon": "media/sheaf.svg"
        }
      ]
    },
    "views": {
      "sheafContainer": [
        {
          "id": "sheaf.chatView",
          "name": "Realtime Chat",
          "type": "webview"
        }
      ]
    },
    "commands": [
      {
        "command": "sheaf.realtime.toggleSession",
        "title": "Sheaf: Toggle Realtime Session"
      },
      {
        "command": "sheaf.realtime.commitAndRespond",
        "title": "Sheaf: Commit Audio And Request Response"
      }
    ],
    "keybindings": [
      {
        "command": "sheaf.realtime.toggleSession",
        "key": "f16"
      },
      {
        "command": "sheaf.realtime.commitAndRespond",
        "key": "f20"
      }
    ],
    "configuration": {
      "title": "Sheaf Realtime",
      "properties": {
        "sheaf.realtime.openAiApiKey": {
          "type": "string",
          "default": "",
          "description": "OpenAI API key (optional if stored in Secret Storage or OPENAI_API_KEY)."
        },
        "sheaf.realtime.model": {
          "type": "string",
          "default": "gpt-realtime-2"
        },
        "sheaf.realtime.systemPrompt": {
          "type": "string",
          "default": "",
          "description": "Overrides the built-in sheaf VS Code system prompt when non-empty."
        },
        "sheaf.realtime.inputDevice": {
          "type": "string",
          "default": "",
          "description": "Optional microphone device id or substring (see realtime-agent list-input-devices)."
        },
        "sheaf.realtime.safetyIdentifier": {
          "type": "string",
          "default": "",
          "description": "Optional safety identifier header for OpenAI Realtime."
        }
      }
    }
  },
  "scripts": {
    "build": "node esbuild.config.mjs",
    "dev": "node esbuild.config.mjs --watch",
    "lint": "tsc -p tsconfig.json --noEmit",
    "test": "rm -rf .test-dist && tsc -p tsconfig.test.json && node scripts/run-vscode-extension-tests.mjs",
    "clean": "rm -rf out .test-dist node_modules *.vsix"
  },
  "dependencies": {
    "better-sqlite3": "^12.10.0",
    "naudiodon": "^2.3.6",
    "realtime-agent-lib": "*"
  },
  "devDependencies": {
    "@types/node": "^22.10.1",
    "@types/vscode": "^1.85.0",
    "esbuild": "^0.24.0",
    "typescript": "^5.7.2"
  }
}

