import { copyFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { build, context } from "esbuild";

const watch = process.argv.includes("--watch");

const rootDir = dirname(fileURLToPath(import.meta.url));

const extensionOptions = {
  entryPoints: ["src/extension.ts"],
  bundle: true,
  format: "cjs",
  platform: "node",
  target: "es2022",
  sourcemap: watch ? "inline" : false,
  outfile: "out/extension.js",
  external: ["vscode", "better-sqlite3", "naudiodon"],
  logLevel: "info",
};

const webviewOptions = {
  entryPoints: ["src/chat/webview/index.ts"],
  bundle: true,
  format: "iife",
  platform: "browser",
  target: "es2022",
  sourcemap: watch ? "inline" : false,
  outfile: "out/webview/index.js",
  logLevel: "info",
};

function CopyWebviewStyles()
{
  mkdirSync(join(rootDir, "out", "webview"), { recursive: true });
  copyFileSync(join(rootDir, "src", "chat", "webview", "index.css"), join(rootDir, "out", "webview", "index.css"));
}

if (watch)
{
  const ctxExt = await context(extensionOptions);
  const ctxWeb = await context(webviewOptions);
  CopyWebviewStyles();
  await Promise.all([ctxExt.watch(), ctxWeb.watch()]);
}
else
{
  await Promise.all([build(extensionOptions), build(webviewOptions)]);
  CopyWebviewStyles();
}

import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export interface RealtimeAgentPaths
{
  configFile: string;
  apiKeysFile: string;
  defaultPromptFile: string;
  databasePath: string;
  runtimeLogPath: string;
}

const x_configRelative = "config/realtime-agent.json";
const x_apiKeysRelative = "config/api_keys.json";
const x_defaultPromptRelative =
  "projects/realtime-agent/prompts/system-prompts/basic_realtime_conversation_v1.md";
const x_databaseRelative = "data/realtime-agent/realtime-agent.sqlite";
const x_runtimeLogRelative = "logs/realtime-agent/realtime-agent.jsonl";

const x_moduleDir =
  typeof __dirname === "string"
    ? __dirname
    : path.dirname(fileURLToPath(import.meta.url));

export function FindRepositoryRoot(startPath?: string): string | undefined
{
  const startDir = path.resolve(startPath ?? process.cwd());
  let current = startDir;

  while (current !== path.dirname(current))
  {
    const servicesJsonPath = path.join(current, "config", "services.json");
    const structureDir = path.join(current, "structure");

    if (existsSync(servicesJsonPath) && existsSync(structureDir))
    {
      return current;
    }

    current = path.dirname(current);
  }

  return undefined;
}

export function ResolveRepositoryPath(relativePath: string, root?: string): string
{
  const repoRoot = root ?? FindRepositoryRoot(x_moduleDir) ?? FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  return path.join(repoRoot, relativePath);
}

export function GetDefaultRealtimeAgentPaths(root?: string): RealtimeAgentPaths
{
  const repoRoot = root ?? FindRepositoryRoot(x_moduleDir) ?? FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  return {
    configFile: path.join(repoRoot, x_configRelative),
    apiKeysFile: path.join(repoRoot, x_apiKeysRelative),
    defaultPromptFile: path.join(repoRoot, x_defaultPromptRelative),
    databasePath: path.join(repoRoot, x_databaseRelative),
    runtimeLogPath: path.join(repoRoot, x_runtimeLogRelative),
  };
}

export {
  x_apiKeysRelative,
  x_configRelative,
  x_databaseRelative,
  x_defaultPromptRelative,
  x_runtimeLogRelative,
};

import { readFile } from "node:fs/promises";

import {
  FindRepositoryRoot,
  GetDefaultRealtimeAgentPaths,
  ResolveRepositoryPath,
  x_databaseRelative,
  x_defaultPromptRelative,
} from "./repo_paths.js";
import {
  DEFAULT_REALTIME_MODEL,
} from "./types.js";

const x_logsDirRelative = "logs/realtime-agent";
const x_dataDirRelative = "data/realtime-agent";

export interface RealtimeAgentConfig
{
  model: string;
  data_dir: string;
  database_path: string;
  logs_dir: string;
  default_prompt_file: string;
  updated_at?: string;
  version?: number;
}

export interface ResolvedRealtimeAgentConfig extends RealtimeAgentConfig
{
  configFile: string;
  databasePath: string;
  defaultPromptPath: string;
  logsDir: string;
  runtimeLogPath: string;
}

export interface LoadRealtimeAgentConfigOptions
{
  configPath?: string;
  repoRoot?: string;
}

export interface LoadOpenAiApiKeyOptions
{
  apiKeysPath?: string;
  repoRoot?: string;
}

export class ConfigLoadError extends Error
{
  constructor(message: string)
  {
    super(message);
    this.name = "ConfigLoadError";
  }
}

function RequireRepoRoot(repoRoot?: string): string
{
  const resolved = repoRoot ?? FindRepositoryRoot();
  if (resolved === undefined)
  {
    throw new ConfigLoadError("repository root not found");
  }

  return resolved;
}

function BuildDefaultConfig(repoRoot: string): ResolvedRealtimeAgentConfig
{
  const paths = GetDefaultRealtimeAgentPaths(repoRoot);

  return {
    model: DEFAULT_REALTIME_MODEL,
    data_dir: x_dataDirRelative,
    database_path: x_databaseRelative,
    logs_dir: x_logsDirRelative,
    default_prompt_file: x_defaultPromptRelative,
    configFile: paths.configFile,
    databasePath: paths.databasePath,
    defaultPromptPath: paths.defaultPromptFile,
    logsDir: ResolveRepositoryPath(x_logsDirRelative, repoRoot),
    runtimeLogPath: paths.runtimeLogPath,
  };
}

function ResolveConfigPaths(
  config: RealtimeAgentConfig,
  repoRoot: string,
  configFile: string,
  runtimeLogPath: string,
): ResolvedRealtimeAgentConfig
{
  return {
    ...config,
    configFile,
    databasePath: ResolveRepositoryPath(config.database_path, repoRoot),
    defaultPromptPath: ResolveRepositoryPath(config.default_prompt_file, repoRoot),
    logsDir: ResolveRepositoryPath(config.logs_dir, repoRoot),
    runtimeLogPath,
  };
}

export async function LoadRealtimeAgentConfig(
  options: LoadRealtimeAgentConfigOptions = {},
): Promise<ResolvedRealtimeAgentConfig>
{
  const repoRoot = RequireRepoRoot(options.repoRoot);
  const paths = GetDefaultRealtimeAgentPaths(repoRoot);
  const configPath = options.configPath ?? paths.configFile;

  try
  {
    const content = await readFile(configPath, "utf8");
    const parsed = JSON.parse(content) as Partial<RealtimeAgentConfig>;
    const merged: RealtimeAgentConfig = {
      model: parsed.model ?? DEFAULT_REALTIME_MODEL,
      data_dir: parsed.data_dir ?? x_dataDirRelative,
      database_path: parsed.database_path ?? x_databaseRelative,
      logs_dir: parsed.logs_dir ?? x_logsDirRelative,

import { appendFileSync, mkdirSync } from "node:fs";
import path from "node:path";

import {
  GetDefaultRealtimeAgentPaths,
} from "./repo_paths.js";

export interface RuntimeLogEntry
{
  timestamp: string;
  level: "info" | "warn" | "error";
  event: string;
  message?: string;
  fields?: Record<string, unknown>;
}

export interface RuntimeLoggerOptions
{
  logPath?: string;
  repoRoot?: string;
}

export interface RuntimeLogger
{
  Log(event: string, fields?: Record<string, unknown>): void;
  LogWarn(event: string, fields?: Record<string, unknown>): void;
  LogError(event: string, fields?: Record<string, unknown>): void;
  Close(): void;
}

const x_sensitiveFieldPattern = /api[_-]?key|authorization|secret|token|password/i;

function SanitizeFields(
  fields?: Record<string, unknown>,
): Record<string, unknown> | undefined
{
  if (fields === undefined)
  {
    return undefined;
  }

  const sanitized: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(fields))
  {
    if (x_sensitiveFieldPattern.test(key))
    {
      sanitized[key] = "[redacted]";
      continue;
    }

    if (key === "pcmBase64" || key === "audio" || key === "frame")
    {
      sanitized[key] = "[redacted]";
      continue;
    }

    sanitized[key] = value;
  }

  return sanitized;
}

function BuildEntry(
  level: RuntimeLogEntry["level"],
  event: string,
  fields?: Record<string, unknown>,
): RuntimeLogEntry
{
  return {
    timestamp: new Date().toISOString(),
    level,
    event,
    fields: SanitizeFields(fields),
  };
}

export function CreateRuntimeLogger(options: RuntimeLoggerOptions = {}): RuntimeLogger
{
  const logPath =
    options.logPath ?? GetDefaultRealtimeAgentPaths(options.repoRoot).runtimeLogPath;

  mkdirSync(path.dirname(logPath), { recursive: true });

  const write = (entry: RuntimeLogEntry): void =>
  {
    appendFileSync(logPath, `${JSON.stringify(entry)}\n`, "utf8");
  };

  return {
    Log(event, fields)
    {
      write(BuildEntry("info", event, fields));
    },
    LogWarn(event, fields)
    {
      write(BuildEntry("warn", event, fields));
    },
    LogError(event, fields)
    {

      logs_dir: parsed.logs_dir ?? x_logsDirRelative,
      default_prompt_file: parsed.default_prompt_file ?? x_defaultPromptRelative,
      updated_at: parsed.updated_at,
      version: parsed.version,
    };

    return ResolveConfigPaths(merged, repoRoot, configPath, paths.runtimeLogPath);
  }
  catch (error)
  {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === "ENOENT")
    {
      return BuildDefaultConfig(repoRoot);
    }

    const message = error instanceof Error ? error.message : String(error);
    throw new ConfigLoadError(`Failed to load ${configPath}: ${message}`);
  }
}

export async function LoadOpenAiApiKey(
  options: LoadOpenAiApiKeyOptions = {},
): Promise<string>
{
  const repoRoot = RequireRepoRoot(options.repoRoot);
  const paths = GetDefaultRealtimeAgentPaths(repoRoot);
  const apiKeysPath = options.apiKeysPath ?? paths.apiKeysFile;

  try
  {
    const content = await readFile(apiKeysPath, "utf8");
    const parsed = JSON.parse(content) as { openai_api_key?: unknown };
    const apiKey =
      typeof parsed.openai_api_key === "string" ? parsed.openai_api_key.trim() : "";

    if (apiKey.length > 0)
    {
      return apiKey;
    }
  }
  catch (error)
  {
    const code = (error as NodeJS.ErrnoException).code;
    if (code !== "ENOENT")
    {
      const message = error instanceof Error ? error.message : String(error);
      throw new ConfigLoadError(`Failed to load ${apiKeysPath}: ${message}`);
    }
  }

  throw new ConfigLoadError(
    `OpenAI API key not found. Add "openai_api_key" to ${apiKeysPath}.`,
  );
}

import * as vscode from "vscode";

import { RegisterRealtimeCommands } from "./commands.js";
import { ChatModel } from "./chat/chatModel.js";
import { ChatViewProvider } from "./chat/chatViewProvider.js";
import { FreshnessCoordinator } from "./freshness/freshnessCoordinator.js";
import { Log } from "./log.js";
import { SessionController } from "./sessionController.js";
import {
  CreateSessionHostFromExtensionContext,
  CreateSessionSecretsFromContext,
  CreateVscodeSessionUi,
  CreateWorkspaceSessionPreferences,
} from "./sessionWiring.js";
import { CreateSheafRealtimeStatusBar, UpdateSheafRealtimeStatusBar } from "./statusBar.js";
import { BuildVscodeToolCallSet } from "./tools/callSetBuilder.js";
import { CreateVscodeEditorAccess } from "./tools/editorAccess.js";

export { CMD_COMMIT_AND_RESPOND, CMD_TOGGLE_SESSION } from "./commands.js";

let g_session: SessionController | undefined;
let g_statusBar: vscode.StatusBarItem | undefined;

export function activate(context: vscode.ExtensionContext): void
{
  const channel = vscode.window.createOutputChannel("Sheaf Realtime");
  const log = new Log(channel);
  context.subscriptions.push(channel);

  const statusBar = CreateSheafRealtimeStatusBar();
  g_statusBar = statusBar;
  context.subscriptions.push(statusBar);

  const host = CreateSessionHostFromExtensionContext(context);
  const secrets = CreateSessionSecretsFromContext(context);
  const prefs = CreateWorkspaceSessionPreferences();
  const ui = CreateVscodeSessionUi();

  const chatModel = new ChatModel();
  const freshnessCoordinator = new FreshnessCoordinator();
  const editorAccess = CreateVscodeEditorAccess();
  const vscodeToolCallSet = BuildVscodeToolCallSet({
    editorAccess,
    freshness: freshnessCoordinator.hooks,
  });

  const session = new SessionController(
    host,
    log,
    secrets,
    prefs,
    ui,
    {
      chatModel,
      freshnessCoordinator,
      buildVscodeToolCallSet: () => vscodeToolCallSet,
    },
    (state) =>
    {
      UpdateSheafRealtimeStatusBar(statusBar, state);
    },
  );
  g_session = session;
  UpdateSheafRealtimeStatusBar(statusBar, session.GetState());

  context.subscriptions.push(
    vscode.window.registerWebviewViewProvider(
      ChatViewProvider.viewType,
      new ChatViewProvider(context.extensionUri, session, chatModel),
    ),
  );

  RegisterRealtimeCommands(context, {
    toggleSession: () => session.ToggleSession(),
    commitAndRespond: () => session.CommitAndRespond(),
  });
}

export async function deactivate(): Promise<void>
{
  if (g_session !== undefined)
  {
    await g_session.Dispose();
    g_session = undefined;
  }

  g_statusBar = undefined;
}

