import assert from "node:assert/strict";
import { test } from "node:test";

import {
  ResolveOpenAiApiKey,
  x_missingOpenAiApiKeyMessage,
} from "../../src/vscode-extension/src/configCore.js";

test("ResolveOpenAiApiKey prefers Secret Storage over repo config over setting", () =>
{
  assert.equal(
    ResolveOpenAiApiKey({
      secretValue: "secret",
      repoConfigValue: "repo",
      settingValue: "setting",
    }),
    "secret",
  );
  assert.equal(
    ResolveOpenAiApiKey({
      repoConfigValue: "repo",
      settingValue: "setting",
    }),
    "repo",
  );
  assert.equal(
    ResolveOpenAiApiKey({
      settingValue: "setting",
    }),
    "setting",
  );
  assert.equal(
    ResolveOpenAiApiKey({
      settingValue: "  ",
    }),
    undefined,
  );
});

test("ResolveOpenAiApiKey ignores blank higher-priority values", () =>
{
  assert.equal(
    ResolveOpenAiApiKey({
      secretValue: "   ",
      repoConfigValue: "repo",
      settingValue: "setting",
    }),
    "repo",
