    sendRealtimeEvent: async () => ({ status: "sent" as const }),
    clearAudioBuffer: async () => ({ status: "sent" as const }),
    stop: async (reason) =>
    {
      onStop(reason);
      return {} as SessionRow;
    },
  };
}

